const items = $input.all();

return items.map((item) => {
  const data = item.json;

  // Gemini response text
  const rawText =
    data.candidates?.[0]?.content?.parts?.[0]?.text ??
    data.content?.parts?.[0]?.text ??
    data.text ??
    "";

  if (!rawText) {
    return {
      json: {
        classification: "Needs Review",
        risk_score: null,
        reasons: ["Gemini response text empty or unavailable."],
        suspicious_urls: [],
        recommended_action: "Review the email manually.",
        missing_information: ["Gemini model output missing"],
        raw_response: "",
        analyzed_at: new Date().toISOString()
      }
    };
  }

  // Remove Markdown code fences if present
  const cleaned = rawText
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  let report = {};
  try {
    report = JSON.parse(cleaned);
  } catch (err) {
    report = {
      classification: "Needs Review",
      risk_score: null,
      reasons: [rawText],
      suspicious_urls: [],
      recommended_action: "Review email manually; raw AI response was non-JSON.",
      missing_information: ["Structured AI parsing failed"]
    };
  }

  // Validate and normalize fields
  const allowed = ["Safe", "Suspicious", "Phishing"];
  const classification = allowed.includes(report.classification)
    ? report.classification
    : "Suspicious";

  const score = Number(report.risk_score);
  const risk_score = Number.isFinite(score)
    ? Math.max(0, Math.min(100, Math.round(score)))
    : null;

  return {
    json: {
      classification,
      risk_score,
      reasons: Array.isArray(report.reasons) ? report.reasons : [],
      suspicious_urls: Array.isArray(report.suspicious_urls) ? report.suspicious_urls : [],
      recommended_action: report.recommended_action ?? "Review the email manually.",
      missing_information: Array.isArray(report.missing_information) ? report.missing_information : [],
      raw_response: rawText,
      analyzed_at: new Date().toISOString()
    }
  };
});

const gemini = $input.first()?.json || {};
const email = $("Get a message").first()?.json || {};

// Combine plain text, html body, and snippet
const textSources = [
  email.textPlain || "",
  email.textHtml || "",
  email.snippet || ""
].join("\n");

// URL Regex to extract all http/https URLs
const urlRegex = /https?:\/\/[^\s<>"'()\[\]{}|\\^`]+/gi;
const matchedUrls = textSources.match(urlRegex) || [];

// Add any suspicious URLs flagged directly by Gemini
const geminiUrls = Array.isArray(gemini.suspicious_urls) ? gemini.suspicious_urls : [];

// Normalize and deduplicate URLs
const allCandidates = [...matchedUrls, ...geminiUrls];
const validUrls = [...new Set(
  allCandidates
    .filter(u => typeof u === "string")
    .map(u => u.trim().replace(/[.,;:]+$/, ""))
    .filter(u => {
      try {
        const p = new URL(u);
        return p.protocol === "http:" || p.protocol === "https:";
      } catch {
        return false;
      }
    })
)];

if (validUrls.length === 0) {
  return [{
    json: {
      has_urls: false,
      url_count: 0,
      urls: [],
      virustotal_lookup_url: null,
      status: "No eligible URLs found"
    }
  }];
}

// For VirusTotal API v3 URL lookup: RFC 4648 base64url encoded without padding
return validUrls.slice(0, 5).map((url, index) => {
  const urlId = Buffer.from(url, "utf8")
    .toString("base64")
    .replace(/=+$/, "")
    .replace(/\+/g, "-")
    .replace(/\//g, "_");

  return {
    json: {
      has_urls: true,
      original_url: url,
      url_id: urlId,
      url_index: index,
      total_urls: validUrls.length,
      virustotal_lookup_url: `https://www.virustotal.com/api/v3/urls/${urlId}`
    }
  };
});

const items = $input.all();
const results = items.map(item => {
  const data = item.json;
  const respData = data.data || {};
  const attributes = respData.attributes || {};
  const stats = attributes.last_analysis_stats || {};
  const origUrl = item.json.original_url || attributes.url || "Unknown URL";

  return {
    original_url: origUrl,
    url_id: respData.id || item.json.url_id || null,
    reputation: attributes.reputation ?? 0,
    analysis_stats: {
      malicious: stats.malicious ?? 0,
      suspicious: stats.suspicious ?? 0,
      harmless: stats.harmless ?? 0,
      undetected: stats.undetected ?? 0
    },
    last_analysis_date: attributes.last_analysis_date
      ? new Date(attributes.last_analysis_date * 1000).toISOString()
      : null,
    report_url: respData.id ? `https://www.virustotal.com/gui/url/${respData.id}` : null
  };
});

const totalMalicious = results.reduce((sum, r) => sum + r.analysis_stats.malicious, 0);
const totalSuspicious = results.reduce((sum, r) => sum + r.analysis_stats.suspicious, 0);

return [{
  json: {
    url_scan_status: totalMalicious > 0 ? "Malicious" : (totalSuspicious > 0 ? "Suspicious" : "Clean"),
    url_scan_reason: `${results.length} URL(s) scanned via VirusTotal`,
    url_scan_count: results.length,
    url_results: results,
    total_malicious_urls: totalMalicious,
    total_suspicious_urls: totalSuspicious
  }
}];

const items = $input.all();

return items.map(item => {
  const binary = item.binary ?? {};
  const keys = Object.keys(binary);

  const attachments = keys.map(key => ({
    binary_key: key,
    file_name: binary[key].fileName ?? key,
    mime_type: binary[key].mimeType ?? "application/octet-stream",
    file_size: binary[key].fileSize ?? null
  }));

  return {
    json: {
      email_id: item.json.id ?? null,
      attachment_count: attachments.length,
      attachments,
      attachment_status: attachments.length
        ? "Ready to scan"
        : "No attachments"
    },
    binary
  };
});

const response = $input.first().json;
const data = response.data ?? response;
const attributes = data.attributes ?? {};
const stats = attributes.stats ?? {};

return [{
  json: {
    analysis_id: data.id ?? null,
    scan_status: attributes.status ?? "unknown",
    scan_date: attributes.date
      ? new Date(attributes.date * 1000).toISOString()
      : null,
    malicious: stats.malicious ?? 0,
    suspicious: stats.suspicious ?? 0,
    harmless: stats.harmless ?? 0,
    undetected: stats.undetected ?? 0,
    total_engines: Object.keys(attributes.results ?? {}).length,
    file_analysis: attributes.results ?? {},
    virus_total_report_url: data.links?.item
      ? `https://www.virustotal.com/gui/file/${data.id}`
      : null
  }
}];

const merged = $input.first()?.json ?? {};
const ai = $("Normalize Gemini Email Analysis").first()?.json ?? {};
const email = $("Get a message").first()?.json ?? {};

// 1. Gemini Risk Assessment
let geminiScore = Number(ai.risk_score);
const hasGeminiScore = Number.isFinite(geminiScore);
if (hasGeminiScore) {
  geminiScore = Math.max(0, Math.min(100, Math.round(geminiScore)));
}

// 2. URL Scan Results
const urlResults = Array.isArray(merged.url_results) ? merged.url_results : [];
const urlMalicious = urlResults.reduce((sum, r) => sum + (r.analysis_stats?.malicious || 0), 0);
const urlSuspicious = urlResults.reduce((sum, r) => sum + (r.analysis_stats?.suspicious || 0), 0);
const urlStatus = merged.url_scan_status || (urlResults.length > 0 ? "Completed" : "Skipped");

// 3. Attachment Scan Results
const attachStats = merged.attachment_stats || {
  malicious: merged.malicious ?? 0,
  suspicious: merged.suspicious ?? 0,
  harmless: merged.harmless ?? 0,
  undetected: merged.undetected ?? 0
};
const attachMalicious = attachStats.malicious || 0;
const attachSuspicious = attachStats.suspicious || 0;
const attachStatus = merged.attachment_scan_status || merged.scan_status || "Unknown";

// 4. Authentication Signals (SPF/DKIM/DMARC)
const authResults = String(
  email.headers?.["authentication-results"] ||
  email["authentication-results"] ||
  ""
).toLowerCase();

const dkimPass = authResults.includes("dkim=pass");
const spfPass = authResults.includes("spf=pass");
const dmarcPass = authResults.includes("dmarc=pass");
const authFail =
  authResults.includes("dkim=fail") ||
  authResults.includes("spf=fail") ||
  authResults.includes("dmarc=fail");

// 5. Multi-factor Explainable Risk Scoring (0 - 100)
let score = 0;
const scoreBreakdown = [];

// A. AI Content Analysis (up to 50 pts)
if (hasGeminiScore) {
  const aiContribution = Math.round(geminiScore * 0.5);
  score += aiContribution;
  scoreBreakdown.push(`Gemini AI content risk analysis (${geminiScore}/100): +${aiContribution} pts`);
} else {
  score += 30;
  scoreBreakdown.push("Gemini AI content analysis unavailable: default +30 pts baseline");
}

// B. VirusTotal Attachment Threat Intel (up to 45 pts)
if (attachMalicious > 0) {
  const attachPoints = Math.min(45, attachMalicious * 20);
  score += attachPoints;
  scoreBreakdown.push(`Malicious attachment flagged by ${attachMalicious} engine(s): +${attachPoints} pts`);
} else if (attachSuspicious > 0) {
  const suspPoints = Math.min(20, attachSuspicious * 10);
  score += suspPoints;
  scoreBreakdown.push(`Suspicious attachment flagged by ${attachSuspicious} engine(s): +${suspPoints} pts`);
}

// C. VirusTotal URL Threat Intel (up to 40 pts)
if (urlMalicious > 0) {
  const urlPoints = Math.min(40, urlMalicious * 15);
  score += urlPoints;
  scoreBreakdown.push(`Malicious URL(s) flagged by ${urlMalicious} engine(s): +${urlPoints} pts`);
} else if (urlSuspicious > 0) {
  const suspUrlPoints = Math.min(20, urlSuspicious * 8);
  score += suspUrlPoints;
  scoreBreakdown.push(`Suspicious URL(s) flagged by ${urlSuspicious} engine(s): +${suspUrlPoints} pts`);
}

// D. Authentication Verification Signal
if (authFail) {
  score += 15;
  scoreBreakdown.push("Email authentication check failed (SPF/DKIM/DMARC fail): +15 pts");
} else if (dkimPass && spfPass && score > 10 && attachMalicious === 0 && urlMalicious === 0) {
  score = Math.max(0, score - 10);
  scoreBreakdown.push("Verified sender domain (SPF and DKIM pass): -10 pts credit");
}

// Clamp final score to 0..100
score = Math.max(0, Math.min(100, Math.round(score)));

// E. Classification based on user's exact specification
let level = "Needs Review";
if (!hasGeminiScore && urlStatus === "Skipped" && attachStatus === "Skipped") {
  level = "Scan Incomplete";
} else if (score <= 25) {
  level = "Low Risk";
} else if (score <= 50) {
  level = "Moderate Risk";
} else if (score <= 75) {
  level = "High Risk";
} else {
  level = "Critical";
}

// 6. Summary and Recommendations
const summary =
  ai.summary ??
  ai.analysis ??
  (Array.isArray(ai.reasons) && ai.reasons.length > 0 ? ai.reasons.join(". ") : (ai.raw_response || "Analysis complete."));

const recommendations =
  Array.isArray(ai.recommendations) && ai.recommendations.length > 0
    ? ai.recommendations
    : score >= 51
      ? ["Do not click any links or download attachments from this email.", "Report this email as phishing.", "Delete or quarantine the message immediately."]
      : score >= 26
        ? ["Verify sender address before replying or acting on requests.", "Check links carefully before clicking."]
        : ["No immediate threats detected. Remain cautious with unsolicited requests."];

// 7. Output Final Report
return [{
  json: {
    report_generated_at: new Date().toISOString(),

    email: {
      email_id: email.id ?? null,
      thread_id: email.threadId ?? null,
      sender: email.from?.text ?? email.from ?? email.headers?.from ?? "Unknown sender",
      subject: email.subject ?? email.headers?.subject ?? "No Subject",
      received_at: email.date ?? email.headers?.date ?? new Date().toISOString()
    },

    risk_score: score,
    risk_level: level,
    score_breakdown: scoreBreakdown,

    ai_analysis: {
      classification: ai.classification ?? level,
      summary,
      reasons: Array.isArray(ai.reasons) ? ai.reasons : [],
      recommendations,
      raw_response: ai.raw_response ?? ""
    },

    url_scan: {
      status: urlStatus,
      reason: merged.url_scan_reason ?? (urlResults.length > 0 ? "Scanned via VirusTotal" : "No URLs eligible for scan"),
      url_count: urlResults.length,
      results: urlResults
    },

    attachment_scan: {
      status: attachStatus,
      reason: merged.attachment_scan_reason ?? (attachStatus === "Skipped" ? "No attachments found" : "Analyzed via VirusTotal"),
      hash: merged.attachment_hash ?? null,
      stats: attachStats,
      total_engines: merged.attachment_total_engines ?? merged.total_engines ?? 0,
      report_url: merged.attachment_report_url ?? merged.virus_total_report_url ?? null
    },

    note: "AI risk scores are estimates. Skipped or incomplete scans do not establish that an email is safe. Percentage values represent system risk scores, not a statistical probability of phishing."
  }
}];

return [{
  json: {
    url_scan_status: "Skipped",
    url_scan_reason: "No eligible URLs found in this email",
    url_scan_count: 0,
    url_results: [],
    total_malicious_urls: 0,
    total_suspicious_urls: 0
  }
}];

const response = $input.first().json;
const data = response.data ?? response;
const attributes = data.attributes ?? {};
const stats = attributes.stats ?? {};

const fileHash = data.links?.item?.split("/files/")[1] ?? null;

return [{
  json: {
    attachment_scan_status: attributes.status ?? "unknown",
    attachment_hash: fileHash,
    attachment_scan_date: attributes.date
      ? new Date(attributes.date * 1000).toISOString()
      : null,
    attachment_stats: {
      malicious: stats.malicious ?? 0,
      suspicious: stats.suspicious ?? 0,
      harmless: stats.harmless ?? 0,
      undetected: stats.undetected ?? 0
    },
    attachment_total_engines: Object.values(
      attributes.stats ?? {}
    ).reduce((sum, count) => sum + count, 0),
    attachment_report_url: fileHash
      ? `https://www.virustotal.com/gui/file/${fileHash}`
      : null
  }
}];

return [{
  json: {
    attachment_scan_status: "Skipped",
    attachment_scan_reason: "No attachments found in this email",
    attachment_hash: null,
    attachment_stats: {
      malicious: 0,
      suspicious: 0,
      harmless: 0,
      undetected: 0
    },
    attachment_total_engines: 0,
    attachment_report_url: null
  }
}];

const items = $input.all();
const query = $("Webhook").first()?.json?.query || {};
const requestedId = query.email_id || query.id || query.thread_id || null;

const row = items[0]?.json || {};
const hasReport = Boolean(row.report_json || row.email_id || (row.risk_score !== undefined && row.risk_score !== null));

if (!hasReport || !row.email_id) {
  return [{
    json: {
      ok: false,
      found: false,
      error: "REPORT_NOT_FOUND",
      message: "No saved security report was found for this email.",
      requested_id: requestedId
    }
  }];
}

let parsedReport = null;
if (typeof row.report_json === "string") {
  try {
    parsedReport = JSON.parse(row.report_json);
  } catch (e) {
    parsedReport = { raw: row.report_json, error: "Report JSON parsing failed: " + e.message };
  }
} else if (typeof row.report_json === "object" && row.report_json !== null) {
  parsedReport = row.report_json;
}

return [{
  json: {
    ok: true,
    found: true,
    email_id: row.email_id,
    subject: row.subject || parsedReport?.email?.subject || "No Subject",
    risk_score: row.risk_score !== undefined ? Number(row.risk_score) : (parsedReport?.risk_score ?? null),
    risk_level: row.risk_level || parsedReport?.risk_level || "Needs Review",
    scanned_at: row.scanned_at || parsedReport?.report_generated_at || null,
    report: parsedReport
  }
}];
